    colors = {v for row in grid for v in row}
    sep = next(
        v for v in colors
        if any(all(x == v for x in row) for row in grid)
        and any(all(grid[r][c] == v for r in range(h)) for c in range(w))
    )

    sep_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def blocks(n, cuts):
        result = []
        start = 0
        for p in cuts:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < n:
            result.append((start, n))
        return result

    rows, cols = blocks(h, sep_rows), blocks(w, sep_cols)
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def signal_count(i, j):
        a, b = rows[i]
        x, y = cols[j]
        return sum(grid[r][c] != bg and grid[r][c] != sep
                   for r in range(a, b) for c in range(x, y))

    source = max(
        ((i, j) for i in range(len(rows)) for j in range(len(cols))),
        key=lambda p: signal_count(*p)
    )
    r0, r1 = rows[source[0]]
    c0, c1 = cols[source[1]]
    out = [row[:] for row in grid]

    for i, (a, b) in enumerate(rows):
        for j, (x, y) in enumerate(cols):
            if (i, j) == source:
                continue
            for dr in range(min(b - a, r1 - r0)):
                for dc in range(min(y - x, c1 - c0)):
                    v = grid[r0 + dr][c0 + dc]
                    if v != bg and v != sep:
